module axixclk #(
	parameter integer C_S_AXI_ID_WIDTH	= 2,
	parameter integer C_S_AXI_DATA_WIDTH	= 32,
	parameter integer C_S_AXI_ADDR_WIDTH	= 6,
	parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
	parameter [0:0]	OPT_READ_ONLY = 1'b0,
	parameter	XCLOCK_FFS = 2,
	parameter	LGFIFO = 5
) (
	input	wire				S_AXI_ACLK,
	input	wire				S_AXI_ARESETN,
	input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
	input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
	input	wire [7 : 0]			S_AXI_AWLEN,
	input	wire [2 : 0]			S_AXI_AWSIZE,
	input	wire [1 : 0]			S_AXI_AWBURST,
	input	wire				S_AXI_AWLOCK,
	input	wire [3 : 0]			S_AXI_AWCACHE,
	input	wire [2 : 0]			S_AXI_AWPROT,
	input	wire [3 : 0]			S_AXI_AWQOS,
	input	wire				S_AXI_AWVALID,
	output	wire				S_AXI_AWREADY,
	input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
	input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
	input	wire				S_AXI_WLAST,
	input	wire				S_AXI_WVALID,
	output	wire				S_AXI_WREADY,
	output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
	output	wire [1 : 0]			S_AXI_BRESP,
	output	wire				S_AXI_BVALID,
	input	wire				S_AXI_BREADY,
	input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
	input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
	input	wire [7 : 0]			S_AXI_ARLEN,
	input	wire [2 : 0]			S_AXI_ARSIZE,
	input	wire [1 : 0]			S_AXI_ARBURST,
	input	wire				S_AXI_ARLOCK,
	input	wire [3 : 0]			S_AXI_ARCACHE,
	input	wire [2 : 0]			S_AXI_ARPROT,
	input	wire [3 : 0]			S_AXI_ARQOS,
	input	wire				S_AXI_ARVALID,
	output	wire				S_AXI_ARREADY,
	output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
	output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
	output	wire [1 : 0]			S_AXI_RRESP,
	output	wire				S_AXI_RLAST,
	output	wire				S_AXI_RVALID,
	input	wire				S_AXI_RREADY,
	input	wire				M_AXI_ACLK,
	output	wire				M_AXI_ARESETN,
	output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
	output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
	output	wire [7 : 0]			M_AXI_AWLEN,
	output	wire [2 : 0]			M_AXI_AWSIZE,
	output	wire [1 : 0]			M_AXI_AWBURST,
	output	wire				M_AXI_AWLOCK,
	output	wire [3 : 0]			M_AXI_AWCACHE,
	output	wire [2 : 0]			M_AXI_AWPROT,
	output	wire [3 : 0]			M_AXI_AWQOS,
	output	wire				M_AXI_AWVALID,
	input	wire				M_AXI_AWREADY,
	output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
	output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
	output	wire				M_AXI_WLAST,
	output	wire				M_AXI_WVALID,
	input	wire				M_AXI_WREADY,
	input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
	input	wire [1 : 0]			M_AXI_BRESP,
	input	wire				M_AXI_BVALID,
	output	wire				M_AXI_BREADY,
	output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
	output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
	output	wire [7 : 0]			M_AXI_ARLEN,
	output	wire [2 : 0]			M_AXI_ARSIZE,
	output	wire [1 : 0]			M_AXI_ARBURST,
	output	wire				M_AXI_ARLOCK,
	output	wire [3 : 0]			M_AXI_ARCACHE,
	output	wire [2 : 0]			M_AXI_ARPROT,
	output	wire [3 : 0]			M_AXI_ARQOS,
	output	wire				M_AXI_ARVALID,
	input	wire				M_AXI_ARREADY,
	input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
	input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
	input	wire [1 : 0]			M_AXI_RRESP,
	input	wire				M_AXI_RLAST,
	input	wire				M_AXI_RVALID,
	output	wire				M_AXI_RREADY
);

localparam integer AW_FIFO_DEPTH = (1 << LGFIFO);
localparam integer AW_FIFO_PTR_W = LGFIFO;
localparam integer W_FIFO_DEPTH = (1 << LGFIFO);
localparam integer W_FIFO_PTR_W = LGFIFO;
localparam integer B_FIFO_DEPTH = (1 << LGFIFO);
localparam integer B_FIFO_PTR_W = LGFIFO;
localparam integer AR_FIFO_DEPTH = (1 << LGFIFO);
localparam integer AR_FIFO_PTR_W = LGFIFO;
localparam integer R_FIFO_DEPTH = (1 << LGFIFO);
localparam integer R_FIFO_PTR_W = LGFIFO;

localparam integer AW_DATA_W = C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 8 + 3 + 2 + 1 + 4 + 3 + 4;
localparam integer W_DATA_W = C_S_AXI_DATA_WIDTH + (C_S_AXI_DATA_WIDTH/8) + 1;
localparam integer B_DATA_W = C_S_AXI_ID_WIDTH + 2;
localparam integer AR_DATA_W = C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 8 + 3 + 2 + 1 + 4 + 3 + 4;
localparam integer R_DATA_W = C_S_AXI_ID_WIDTH + C_S_AXI_DATA_WIDTH + 2 + 1;

// Reset synchronization
reg [1:0] m_reset_sync;
reg m_reset_n;

always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		m_reset_sync <= 2'b00;
		m_reset_n <= 1'b0;
	end else begin
		m_reset_sync <= {m_reset_sync[0], 1'b1};
		m_reset_n <= m_reset_sync[1];
	end
end

assign M_AXI_ARESETN = m_reset_n;

// AW channel: S to M
reg [AW_FIFO_DEPTH-1:0][AW_DATA_W-1:0] aw_fifo_mem;
reg [AW_FIFO_PTR_W:0] aw_wr_ptr;
reg [AW_FIFO_PTR_W:0] aw_rd_ptr;
reg [AW_FIFO_PTR_W:0] aw_rd_ptr_sync0, aw_rd_ptr_sync1;

wire aw_fifo_full = (aw_wr_ptr - aw_rd_ptr_sync1) == AW_FIFO_DEPTH;
wire aw_fifo_empty = (aw_wr_ptr == aw_rd_ptr_sync1);

wire aw_write_en = S_AXI_AWVALID && S_AXI_AWREADY;
assign S_AXI_AWREADY = !aw_fifo_full;

always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		aw_wr_ptr <= 0;
	end else if (aw_write_en) begin
		aw_fifo_mem[aw_wr_ptr[AW_FIFO_PTR_W-1:0]] <= {
			S_AXI_AWID,
			S_AXI_AWADDR,
			S_AXI_AWLEN,
			S_AXI_AWSIZE,
			S_AXI_AWBURST,
			S_AXI_AWLOCK,
			S_AXI_AWCACHE,
			S_AXI_AWPROT,
			S_AXI_AWQOS
		};
		aw_wr_ptr <= aw_wr_ptr + 1;
	end
end

// Synchronize read pointer to S domain
always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		aw_rd_ptr_sync0 <= 0;
		aw_rd_ptr_sync1 <= 0;
	end else begin
		aw_rd_ptr_sync0 <= aw_rd_ptr;
		aw_rd_ptr_sync1 <= aw_rd_ptr_sync0;
	end
end

// AW channel: M side read
wire [AW_DATA_W-1:0] aw_fifo_data = aw_fifo_mem[aw_rd_ptr[AW_FIFO_PTR_W-1:0]];
wire aw_read_en = M_AXI_AWVALID && M_AXI_AWREADY;

assign M_AXI_AWVALID = !aw_fifo_empty;
assign M_AXI_AWID = aw_fifo_data[AW_DATA_W-1 -: C_S_AXI_ID_WIDTH];
assign M_AXI_AWADDR = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-1 -: C_S_AXI_ADDR_WIDTH];
assign M_AXI_AWLEN = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-1 -: 8];
assign M_AXI_AWSIZE = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-1 -: 3];
assign M_AXI_AWBURST = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-1 -: 2];
assign M_AXI_AWLOCK = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1];
assign M_AXI_AWCACHE = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-1 -: 4];
assign M_AXI_AWPROT = aw_fifo_data[AW_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-1-4-1 -: 3];
assign M_AXI_AWQOS = aw_fifo_data[0:3];

always @(posedge M_AXI_ACLK or negedge m_reset_n) begin
	if (!m_reset_n) begin
		aw_rd_ptr <= 0;
	end else if (aw_read_en) begin
		aw_rd_ptr <= aw_rd_ptr + 1;
	end
end

// W channel: S to M
reg [W_FIFO_DEPTH-1:0][W_DATA_W-1:0] w_fifo_mem;
reg [W_FIFO_PTR_W:0] w_wr_ptr;
reg [W_FIFO_PTR_W:0] w_rd_ptr;
reg [W_FIFO_PTR_W:0] w_rd_ptr_sync0, w_rd_ptr_sync1;

wire w_fifo_full = (w_wr_ptr - w_rd_ptr_sync1) == W_FIFO_DEPTH;
wire w_fifo_empty = (w_wr_ptr == w_rd_ptr_sync1);

wire w_write_en = S_AXI_WVALID && S_AXI_WREADY;
assign S_AXI_WREADY = !w_fifo_full;

always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		w_wr_ptr <= 0;
	end else if (w_write_en) begin
		w_fifo_mem[w_wr_ptr[W_FIFO_PTR_W-1:0]] <= {
			S_AXI_WDATA,
			S_AXI_WSTRB,
			S_AXI_WLAST
		};
		w_wr_ptr <= w_wr_ptr + 1;
	end
end

always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		w_rd_ptr_sync0 <= 0;
		w_rd_ptr_sync1 <= 0;
	end else begin
		w_rd_ptr_sync0 <= w_rd_ptr;
		w_rd_ptr_sync1 <= w_rd_ptr_sync0;
	end
end

// W channel: M side read with extra register
reg [W_DATA_W-1:0] w_data_reg;
reg w_valid_reg;

wire w_read_en = M_AXI_WVALID && M_AXI_WREADY;

always @(posedge M_AXI_ACLK or negedge m_reset_n) begin
	if (!m_reset_n) begin
		w_rd_ptr <= 0;
		w_data_reg <= 0;
		w_valid_reg <= 0;
	end else begin
		if (!w_fifo_empty) begin
			w_data_reg <= w_fifo_mem[w_rd_ptr[W_FIFO_PTR_W-1:0]];
			w_valid_reg <= 1'b1;
		end else begin
			w_valid_reg <= 1'b0;
		end

		if (w_read_en) begin
			w_rd_ptr <= w_rd_ptr + 1;
			w_valid_reg <= 1'b0;
		end
	end
end

assign M_AXI_WVALID = w_valid_reg;
assign M_AXI_WDATA = w_data_reg[W_DATA_W-1 -: C_S_AXI_DATA_WIDTH];
assign M_AXI_WSTRB = w_data_reg[C_S_AXI_DATA_WIDTH-1 -: (C_S_AXI_DATA_WIDTH/8)];
assign M_AXI_WLAST = w_data_reg[0];

// B channel: M to S
reg [B_FIFO_DEPTH-1:0][B_DATA_W-1:0] b_fifo_mem;
reg [B_FIFO_PTR_W:0] b_wr_ptr;
reg [B_FIFO_PTR_W:0] b_rd_ptr;
reg [B_FIFO_PTR_W:0] b_wr_ptr_sync0, b_wr_ptr_sync1;

wire b_fifo_full = (b_wr_ptr - b_rd_ptr_sync1) == B_FIFO_DEPTH;
wire b_fifo_empty = (b_wr_ptr == b_rd_ptr_sync1);

wire b_write_en = M_AXI_BVALID && M_AXI_BREADY;
assign M_AXI_BREADY = !b_fifo_full;

always @(posedge M_AXI_ACLK or negedge m_reset_n) begin
	if (!m_reset_n) begin
		b_wr_ptr <= 0;
	end else if (b_write_en) begin
		b_fifo_mem[b_wr_ptr[B_FIFO_PTR_W-1:0]] <= {
			M_AXI_BID,
			M_AXI_BRESP
		};
		b_wr_ptr <= b_wr_ptr + 1;
	end
end

always @(posedge M_AXI_ACLK or negedge m_reset_n) begin
	if (!m_reset_n) begin
		b_rd_ptr_sync0 <= 0;
		b_rd_ptr_sync1 <= 0;
	end else begin
		b_rd_ptr_sync0 <= b_rd_ptr;
		b_rd_ptr_sync1 <= b_rd_ptr_sync0;
	end
end

// B channel: S side read
wire [B_DATA_W-1:0] b_fifo_data = b_fifo_mem[b_rd_ptr[B_FIFO_PTR_W-1:0]];
wire b_read_en = S_AXI_BVALID && S_AXI_BREADY;

assign S_AXI_BVALID = !b_fifo_empty;
assign S_AXI_BID = b_fifo_data[B_DATA_W-1 -: C_S_AXI_ID_WIDTH];
assign S_AXI_BRESP = b_fifo_data[0:1];

always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		b_rd_ptr <= 0;
	end else if (b_read_en) begin
		b_rd_ptr <= b_rd_ptr + 1;
	end
end

// AR channel: S to M
reg [AR_FIFO_DEPTH-1:0][AR_DATA_W-1:0] ar_fifo_mem;
reg [AR_FIFO_PTR_W:0] ar_wr_ptr;
reg [AR_FIFO_PTR_W:0] ar_rd_ptr;
reg [AR_FIFO_PTR_W:0] ar_rd_ptr_sync0, ar_rd_ptr_sync1;

wire ar_fifo_full = (ar_wr_ptr - ar_rd_ptr_sync1) == AR_FIFO_DEPTH;
wire ar_fifo_empty = (ar_wr_ptr == ar_rd_ptr_sync1);

wire ar_write_en = S_AXI_ARVALID && S_AXI_ARREADY;
assign S_AXI_ARREADY = !ar_fifo_full;

always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		ar_wr_ptr <= 0;
	end else if (ar_write_en) begin
		ar_fifo_mem[ar_wr_ptr[AR_FIFO_PTR_W-1:0]] <= {
			S_AXI_ARID,
			S_AXI_ARADDR,
			S_AXI_ARLEN,
			S_AXI_ARSIZE,
			S_AXI_ARBURST,
			S_AXI_ARLOCK,
			S_AXI_ARCACHE,
			S_AXI_ARPROT,
			S_AXI_ARQOS
		};
		ar_wr_ptr <= ar_wr_ptr + 1;
	end
end

always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
	if (!S_AXI_ARESETN) begin
		ar_rd_ptr_sync0 <= 0;
		ar_rd_ptr_sync1 <= 0;
	end else begin
		ar_rd_ptr_sync0 <= ar_rd_ptr;
		ar_rd_ptr_sync1 <= ar_rd_ptr_sync0;
	end
end

