assign M_AXI_ARID = ar_fifo_data[AR_DATA_W-1 -: C_S_AXI_ID_WIDTH];
assign M_AXI_ARADDR = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-1 -: C_S_AXI_ADDR_WIDTH];
assign M_AXI_ARLEN = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-1 -: 8];
assign M_AXI_ARSIZE = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-1 -: 3];
assign M_AXI_ARBURST = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-1 -: 2];
assign M_AXI_ARLOCK = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1];
assign M_AXI_ARCACHE = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-1 -: 4];
assign M_AXI_ARPROT = ar_fifo_data[AR_DATA_W-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-1-4-1 -: 3];
assign M_AXI_ARQOS = ar_fifo_data[0:3];

always @(posedge M_AXI_ACLK or negedge m_reset_n) begin
	if (!m_reset_n) begin
		ar_rd_ptr <= 0;
	end else if (ar_read_en) begin
		ar_rd_ptr <= ar_rd_ptr + 1;
	end
