// R channel: M to S
reg [R_FIFO_DEPTH-1:0][R_DATA_W-1:0] r_fifo_mem;
reg [R_FIFO_PTR_W:0] r_wr_ptr;
reg [R_FIFO_PTR_W:0] r_rd_ptr;
reg [R_FIFO_PTR_W:0] r_wr_ptr_sync0, r_wr_ptr_sync1;

